<form class="portal-search" method="get"><label for="portal-search-q">عبارت موردنظر</label><input type="search" id="portal-search-q" name="q" value="{{ request('q') }}" required minlength="2" maxlength="150"><button class="portal-button">جستجو</button></form>@foreach(['contents'=>'مطالب','services'=>'خدمات','faqs'=>'پرسش‌های متداول'] as $key=>$label)@if(!empty($results[$key]))<section class="portal-card"><h2>{{ $label }}</h2>@foreach($results[$key] as $result)<article class="my-5"><h3><a href="{{ $key==='contents'?$ui->article($result,$county):$ui->href($key==='services'?'/service/'.$result['id']:'/faq',$county) }}">{{ $result['title'] ?? $result['name'] ?? $result['question'] }}</a></h3><p>{{ $ui->text($result['excerpt'] ?? $result['description'] ?? $result['answer'] ?? '',240) }}</p></article>@endforeach</section>@endif @endforeach @if(request()->filled('q') && !array_filter($results))<p class="portal-empty">نتیجه‌ای پیدا نشد.</p>@endif
